static struct ListNode*merge(struct ListNode*a,struct ListNode*b){struct ListNode d={0,0},*t=&d;while(a&&b){if(a->val<=b->val){t->next=a;a=a->next;}else{t->next=b;b=b->next;}t=t->next;}t->next=a?a:b;return d.next;}struct ListNode* sortList(struct ListNode*h){if(!h||!h->next)return h;struct ListNode*s=h,*f=h->next;while(f&&f->next){s=s->next;f=f->next->next;}struct ListNode*b=s->next;s->next=0;return merge(sortList(h),sortList(b));}
